#include <bits/stdc++.h>
using namespace std;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);
    int n;
    cin >> n;

    const int maxSize = 2 * n + 1;
    const long long mod = 1000000007;
    vector<vector<long long>> dp(maxSize, vector<long long>(maxSize, 0));
    dp[1][1] = 1;

    for (int i = 2; i <= 2 * n; ++i) {
        for (int j = 0; j <= i; ++j) {
            if (j > 0) {
                dp[i][j] += dp[i - 1][j - 1];
                if (dp[i][j] >= mod) dp[i][j] -= mod;
            }

            if (j < 2 * n) {
                dp[i][j] += dp[i - 1][j + 1];
                if (dp[i][j] >= mod) dp[i][j] -= mod;
            }
        }
    }

    long long ans = 0;
    for (int i = 2 * n - 1; i >= 0; i -= 2) {
        for (int j = 0; j <= i; ++j) {
            if (2 * n - i >= j) {
                ans += dp[i][j];
                if (ans >= mod) ans -= mod;
            }
        }
    }

    cout << ans << "\n";
    return 0;
}

